#!/usr/bin/env node
/**
 * Tests for workflows/dev-loop.js: a P2 counts only with a probe or a quoted file:line (owner decision D2).
 * Zero dependencies — `node:test` on Node 18+; the shared harness is tools/dev-loop.harness.mjs.
 *
 *   node --test "tools/*.test.mjs"
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { FILES, f, classify, run, ARGS_M, review, finding, impl, gate } from './dev-loop.harness.mjs';

const bare = (extra = {}) => f('a', { evidence: undefined, ...extra });
const probes = [{ path: 'deliver/probes/p.mjs', cmd: 'node -e "probe"' }];
const V_ARGS = { ...ARGS_M, verify: 'node --test x' };

test('given a P2 logic finding with no probes and no evidence, when classified, then it is minor', () => {
  // Given
  const x = bare();
  // When
  const kind = classify(x, FILES);
  // Then
  assert.equal(kind, 'minor');
});

test('given a P2 with a probe, or with evidence quoting a file:line, when classified, then it is blocking as today', () => {
  // Given
  const withProbe = bare({ probes });
  const withLine = bare({ evidence: 'src/Orders/OrdersQuery.cs:42 drops the filter' });
  const withoutLine = bare({ evidence: 'it looks wrong' });
  // When
  const kinds = [classify(withProbe, FILES), classify(withLine, FILES), classify(withoutLine, FILES)];
  // Then
  assert.deepEqual(kinds, ['blocking', 'blocking', 'minor']);
});

test('given a P1 without probe, or a P2 scope or security finding without evidence, when classified, then it stays blocking', () => {
  // Given
  const p1 = bare({ priority: 'P1' });
  const scope = bare({ category: 'scope' });
  const security = bare({ category: 'security' });
  // When
  const kinds = [p1, scope, security].map(x => classify(x, FILES));
  // Then
  assert.deepEqual(kinds, ['blocking', 'blocking', 'blocking']);
});

test('given a P2 without probe or evidence outside the perimeter, when classified, then it is out of scope, not a widen', () => {
  // Given
  const x = bare({ path: 'src/Other/Helper.cs' });
  // When
  const kind = classify(x, FILES);
  // Then
  assert.equal(kind, 'outOfScope');
});

test('given a reader reports a P2 with no probe and no evidence, when the loop runs, then no fix round starts', async () => {
  // Given
  const report = review([], [finding({ evidence: undefined })]);
  const impls = [impl({ gate: gate('green', { tree: '' }) })];
  // When
  const { calls } = await run(V_ARGS, [report, review([])], impls);
  // Then
  assert.ok(!calls.some(c => /^fix round/.test(c.opts.label)), calls.map(c => c.opts.label).join(' | '));
});

test('given the reader briefs, when built, then each asks every P2 for a probe or a quoted file:line', async () => {
  // Given
  const impls = [impl({ gate: gate('green', { tree: '' }) })];
  // When
  const { calls } = await run(V_ARGS, [review([])], impls);
  // Then
  const readers = calls.filter(c => /reader|review/i.test(c.opts.label) && c.opts.agentType !== 'implementer');
  assert.ok(readers.length > 0);
  for (const c of readers) assert.match(c.prompt, /every P2 .*probe or an evidence field quoting the file:line/, c.opts.label);
});

test('given P2 evidence that is prose with a slash and a port, when classified, then it is no quoted file:line', () => {
  // Given
  const cases = ['the TCP/IP:80 listener drops the header', 'I/O:3 retries are lost', 'returns HTTP/HTTPS:443 mixed'];

  // When
  const got = cases.map(evidence => classify(bare({ evidence }), FILES));

  // Then
  assert.deepEqual(got, ['minor', 'minor', 'minor']);
});
